import {installSetupAgent,applyAgentProposal} from './setup-agent.js';
import {fetchPackIndex,packLabel,packCaption} from './packs.js';
import {episodeDates} from './m2c.js';
import {SimulationLibrary,studioURL} from './simulation-library.js';
const root=document.getElementById('setup-root'),query=new URLSearchParams(location.search);
const api=(query.get('engine')||'').replace(/\/$/,'')+'/api';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const steps=['Your simulation','Choose a town','Set the scenario','Review & open'];
let library,packs,draft,step=0,scenarios=[],scenarioState='idle',message='',agentOpen=false,closeAgent=null;
const localNote='Saved in this browser. Use the same browser to return to your simulations.';
function alertMessage(text){const el=document.getElementById('setup-message');if(el){el.textContent=text;el.focus();}}
function save(){draft=library.save({...draft,step});}
function showLibrary(){closeAgent?.();closeAgent=null;agentOpen=false;draft=null;message='';history.replaceState(null,'',location.pathname+location.search+'#/simulations');const list=library.list();
 root.innerHTML=`<section class="library"><div class="eyebrow">YOUR WORKSPACE</div><div class="library-heading"><div><h1>Your simulations</h1><p>Pick up an existing simulation, or start with a new question.</p></div><button class="primary" id="new-simulation">＋ New simulation</button></div><p class="storage-note">${localNote} Setup and analyst actions are remembered; live views are recalculated when opened.</p><p id="setup-message" role="alert" tabindex="-1"></p><div class="simulation-grid">${list.map(s=>`<article class="simulation-card"><div class="card-top"><span class="status ${s.status}">${s.status==='draft'?'SETUP IN PROGRESS':'SAVED SIMULATION'}</span><span>2026</span></div><h2>${esc(s.name||'Untitled simulation')}</h2><p>${esc(s.purpose||s.scenarioTitle||'Normal operations')}</p><dl><div><dt>Town</dt><dd>${esc(s.townName||'Not selected')}</dd></div><div><dt>Homes</dt><dd>${s.homes?Number(s.homes).toLocaleString('en-CA'):'—'}</dd></div><div><dt>View date</dt><dd>${esc(s.asOf||'—')}</dd></div></dl><button class="${s.status==='draft'?'secondary':'primary'}" data-open="${esc(s.id)}">${s.status==='draft'?'Continue setup':'Open simulation'} <span aria-hidden="true">→</span></button></article>`).join('')}</div><aside class="archive-note"><strong>Already have downloaded results?</strong><p>Open a saved run to browse its results without recalculating.</p><a href="./runs.html">Open a run folder →</a></aside></section>`;
 document.getElementById('new-simulation').onclick=()=>begin();
 root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{try{const s=library.get(b.dataset.open);if(!s)throw Error('Simulation not found in this browser.');if(s.status==='draft')begin(s);else open(s);}catch(e){alertMessage(e.message);}});
}
function begin(s){agentOpen=false;draft=s||library.create();step=draft.step||0;message='';history.replaceState(null,'',location.pathname+location.search+'#/setup');render();}
function capture(){if(!draft)return;for(const key of ['name','purpose','asOf','seed']){const input=document.getElementById('setup-'+key);if(input)draft[key]=input.value.trim();}}
function selectTown(preset){draft.agentProposal=null;draft.townOverrides={};const t=packs?.towns.find(t=>t.preset===preset);if(!t)return;Object.assign(draft,{preset:t.preset,townRef:t.preset,townId:t.townId,townName:packLabel(t),homes:t.homes});}
function validate(){if(!draft.name.trim())return 'Give your simulation a name.';if(step>=1&&!draft.townRef)return 'Choose a town to continue.';if(step>=2&&(!/^2026-\d{2}-\d{2}$/.test(draft.asOf)||Number.isNaN(Date.parse(draft.asOf))||new Date(draft.asOf).toISOString().slice(0,10)!==draft.asOf))return 'Choose a valid view date in 2026.';return '';}
async function loadScenarios(){if(scenarioState==='loading'||scenarioState==='ready')return;scenarioState='loading';
 try{const r=await fetch(api+'/m2c/scenarios',{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('unavailable');const data=await r.json();if(!Array.isArray(data.scenarios))throw Error('unavailable');scenarios=data.scenarios;scenarioState='ready';}catch{scenarioState='failed';}if(draft&&step===2&&!agentOpen){capture();render(false);}}
const starters=[['baseline','Normal operations','The usual day-to-day.'],['starter_busy','A little busy','A few more hiccups.'],['starter_pressure','Under pressure','A stretched team and rising queues.'],['starter_chaos','Organised chaos','Several things go wrong together.']];
function starterCards(){return `<fieldset class="starter-choices"><legend>Choose your starting intensity</legend>${starters.map(([id,title,note],i)=>{const available=id==='baseline'||scenarios.some(s=>s.id===id);return `<label class="starter-choice ${draft.scenarioId===id?'selected':''}"><input type="radio" name="starter" value="${id}" ${draft.scenarioId===id?'checked':''} ${available?'':'disabled'}><span><small>${'●'.repeat(i+1)}${'○'.repeat(3-i)}</small><strong>${title}</strong><span>${note}${available?'':' · loading requires engine'}</span></span></label>`;}).join('')}</fieldset>`;}
function chooseScenario(id){capture();draft.agentProposal=null;draft.settings={};draft.operations={};draft.opsSettings=null;const s=scenarioChoices().find(s=>s.id===id);if(!s)return;draft.scenarioId=s.id;draft.scenarioTitle=s.title;draft.episodes=s.id==='baseline'?[]:episodeDates(s,'2026-01-01').map((ep,i)=>({...ep,id:'EP-'+(i+1)}));try{save();render(false);}catch(e){alertMessage(e.message);}}
function scenarioChoices(){return [ ...(draft.scenarioId==='custom'?[{id:'custom',title:draft.scenarioTitle,description:draft.summary||'Custom setup from your conversation.'}]:[]),{id:'baseline',title:'Normal operations',description:'Start with the town’s usual staffing, meter reading and billing. You can add changes later in the Year view.'},...scenarios];}
function render(focus=true){
 closeAgent?.();closeAgent=null;
 if(agentOpen){root.innerHTML='<section class="wizard agent-wizard"><aside class="wizard-rail"><div class="eyebrow">CONVERSATIONAL SETUP</div><h2>Your experience.<br>A working scenario.</h2><p>Speak naturally. We’ll translate your answers into the model’s settings.</p><div class="rail-foot">Changes stay in your draft.<br>You review before opening Year.</div></aside><section class="wizard-panel" id="agent-root"></section></section>';
  closeAgent=installSetupAgent({root:document.getElementById('agent-root'),api,getDraft:()=>draft,onSave:agent=>{draft.agent=agent;draft.name||='Untitled simulation';save();},onApply:p=>{draft=applyAgentProposal(draft,p);step=3;save();agentOpen=false;render();},onBack:()=>{agentOpen=false;render();}});return;}
 const agentEntry='<aside class="agent-entry"><div><strong>Build it by talking it through</strong><p>Tell Claude what’s happening at your utility. Answer a few questions, then review a proposed setup.</p></div><button class="secondary" type="button" id="open-agent">Talk it through →</button></aside>';
 const content=[
  ()=>`${agentEntry}<label for="setup-name">Simulation name</label><input id="setup-name" name="name" value="${esc(draft.name)}" maxlength="100" placeholder="e.g. Billing resilience · spring baseline" autocomplete="off" required><label for="setup-purpose">What do you want to explore? <span>Optional</span></label><textarea id="setup-purpose" maxlength="500" rows="3" placeholder="e.g. How does a smaller billing team affect the backlog?">${esc(draft.purpose)}</textarea><div class="help-card"><strong>A little setup. A complete place to explore.</strong><p>Choose a town, set your starting scenario, then open the simulation. You can refine the detailed settings inside Studio.</p></div>`,
  ()=>`<fieldset class="town-choices"><legend class="sr-only">Choose a town</legend>${(packs?.towns||[]).map(t=>`<label class="town-choice ${draft.preset===t.preset?'selected':''}"><input type="radio" name="town" value="${esc(t.preset)}" ${draft.preset===t.preset?'checked':''} required><span><strong>${esc(packLabel(t))}</strong><small>${esc(packCaption(t))}</small></span><span class="town-mark" aria-hidden="true">↗</span></label>`).join('')}</fieldset>${packs?.towns?.length?'<p class="field-note">Each town includes synthetic customers, meters and connected utility networks. Homes and customer accounts are different counts.</p>':'<p class="inline-error">The town catalogue could not load.</p><button type="button" id="retry-packs" class="secondary">Try again</button>'}`,
  ()=>`${agentEntry}${starterCards()}<label for="setup-scenario">Or choose a specific scenario</label><select id="setup-scenario">${scenarioChoices().map(s=>`<option value="${esc(s.id)}" ${draft.scenarioId===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select><p class="field-note" id="scenario-description">${esc(scenarioChoices().find(s=>s.id===draft.scenarioId)?.description||draft.scenarioTitle)}</p>${scenarioState==='failed'?'<p class="field-note">Extra scenarios are unavailable right now. You can start with normal operations.</p><button type="button" class="text-button" id="retry-scenarios">Retry scenarios</button>':scenarioState!=='ready'?'<p class="field-note" role="status">Loading additional scenarios…</p>':''}<label for="setup-asOf">Open at this date</label><input id="setup-asOf" type="date" min="2026-01-01" max="2026-12-31" value="${esc(draft.asOf)}" required><p class="field-note">The model starts on January 1. Studio calculates activity up to your view date. Starting scenarios apply from January 1.</p><details><summary>Repeatability</summary><label for="setup-seed">Run seed <span>Optional</span></label><input id="setup-seed" maxlength="64" value="${esc(draft.seed)}" placeholder="Use the town’s seed" autocomplete="off"><p class="field-note">Keep the same seed and settings to recreate the same results.</p></details><div class="help-card"><strong>One calendar year: 2026</strong><p>Multi-year runs and the downloadable offline runner are still to come. This setup opens in the current Studio.</p></div>`,
  ()=>`${draft.agentProposal?`<p class="agent-review-summary">${esc(draft.agentProposal.summary)}</p><button class="text-button" id="open-agent" type="button">Refine with Claude</button><details><summary>Assumptions and model limits</summary><ul>${[...draft.agentProposal.assumptions,...draft.agentProposal.limitations].map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`:''}<div class="review-name">${esc(draft.name)}</div>${draft.purpose?`<p>${esc(draft.purpose)}</p>`:''}<dl class="review"><div><dt>Town</dt><dd>${esc(draft.townName)} · ${Number(draft.homes).toLocaleString('en-CA')} homes</dd></div><div><dt>Starting scenario</dt><dd>${esc(draft.scenarioTitle)}</dd></div><div><dt>Simulation year</dt><dd>January – December 2026</dd></div><div><dt>Open at</dt><dd>${esc(draft.asOf)}</dd></div><div><dt>Run seed</dt><dd>${esc(draft.seed||'Town default')}</dd></div><div><dt>Saved setup</dt><dd>This browser</dd></div></dl><div class="help-card"><strong>Ready when you are.</strong><p>Your simulation opens in the Year view. Explore results, work exceptions and adjust scenarios from there. Each simulation keeps its own settings and analyst actions.</p></div>`
 ][step]();
 const headings=['What are you exploring?','Choose your starting town.','How should the year begin?','Your simulation, ready to open.'];
 const intros=['Give this simulation a name you’ll recognise when you return.','Start with a prepared town. Its customers and networks are ready to use.','Start with normal operations or explore a change to the utility.','Review your choices. You can go back to change anything.'];
 root.innerHTML=`<div class="wizard"><aside class="wizard-rail"><div class="eyebrow">NEW SIMULATION</div><h2>From a question<br>to a working model.</h2><p>We’ll guide you through the essentials.</p><ol>${steps.map((title,i)=>`<li class="${i===step?'current':i<step?'complete':''}" ${i===step?'aria-current="step"':''}><span>${i<step?'✓':i+1}</span>${title}</li>`).join('')}</ol><div class="rail-foot">Your setup is saved as you go.<br>No account needed.</div></aside><section class="wizard-panel"><div class="wizard-top"><span>STEP ${step+1} OF 4</span><button class="text-button" type="button" id="show-library">My simulations</button></div><h1 tabindex="-1">${headings[step]}</h1><p class="intro">${intros[step]}</p><form id="setup-form">${content}<p id="setup-message" role="alert" tabindex="-1">${esc(message)}</p><div class="wizard-actions"><button class="secondary" id="previous" type="button" ${step===0?'hidden':''}>← Back</button><span></span><button class="primary" type="submit">${step===3?'Open simulation':'Continue'} <span aria-hidden="true">→</span></button></div></form><p class="storage-note">${localNote}</p></section></div>`;
 if(focus)root.querySelector('h1').focus();
 const openAgent=document.getElementById('open-agent');if(openAgent)openAgent.onclick=()=>{capture();agentOpen=true;render();};
 document.getElementById('show-library').onclick=()=>{try{capture();if(draft.name)save();showLibrary();}catch(e){alertMessage(e.message);}};
 document.getElementById('previous').onclick=()=>{try{capture();step--;save();message='';render();}catch(e){alertMessage(e.message);}};
 document.getElementById('setup-form').onsubmit=e=>{e.preventDefault();try{capture();message=validate();if(message){alertMessage(message);return;}if(step===3){draft.status='ready';save();open(draft);}else{step++;save();render();}}catch(err){alertMessage(err.message);}};
 root.querySelectorAll('[name="town"]').forEach(input=>input.onchange=()=>{selectTown(input.value);try{save();render(false);}catch(e){alertMessage(e.message);}});
 const choice=document.getElementById('setup-scenario');if(choice)choice.onchange=()=>chooseScenario(choice.value);
 root.querySelectorAll('[name="starter"]').forEach(input=>input.onchange=()=>chooseScenario(input.value));
 for(const input of root.querySelectorAll('input:not([type="radio"]),textarea'))input.addEventListener('input',()=>{capture();if(draft.name)try{save();}catch(e){alertMessage(e.message);}});
 const retry=document.getElementById('retry-scenarios');if(retry)retry.onclick=()=>{scenarioState='idle';loadScenarios();};
 const retryPacks=document.getElementById('retry-packs');if(retryPacks)retryPacks.onclick=async()=>{packs=await fetchPackIndex();render();};
 if(step===2&&scenarioState==='idle')loadScenarios();
}
function open(s){library.update(s.id,{openedAt:new Date().toISOString()});location.href=studioURL(s,location.search);}
try{library=new SimulationLibrary();packs=await fetchPackIndex();library.adoptPacks(packs);if(library.list().length)showLibrary();else begin();}
catch(e){root.innerHTML=`<section class="library"><h1>Your simulations couldn’t open.</h1><p role="alert">${esc(e.message)}</p><button class="primary" onclick="location.reload()">Try again</button><p>Existing browser data has not been removed.</p></section>`;}
